actions.script:
def uid = ec.user.userId
boolean _d = ec.artifactExecution.disableAuthz()
try {
    boolean isGoogle = ec.entity.find("moqui.security.UserPreference")
            .condition("userId", uid).condition("preferenceKey", "GOOGLE_SUB").count() > 0
    def result = null
    if (isGoogle) {
        // Passwordless Google account — no current password exists to verify. The active
        // (Google-authenticated) session is the authorization; only ever their own userId.
        result = ec.service.sync().name("org.moqui.impl.UserServices.update#PasswordInternal")
                .parameters([userId: uid, newPassword: newPassword, newPasswordVerify: newPasswordVerify]).call()
    } else if (!currentPassword) {
        ec.message.addError("Please enter your current password.")
    } else {
        // update#Password verifies oldPassword against the stored password before changing it.
        result = ec.service.sync().name("org.moqui.impl.UserServices.update#Password")
                .parameters([userId: uid, oldPassword: currentPassword, newPassword: newPassword, newPasswordVerify: newPasswordVerify]).call()
    }
    if (result?.updateSuccessful && !ec.message.hasError()) {
        ec.message.addMessage("Password set. You can now sign in with your username (" + ec.user.username + ") and this password"
                + (isGoogle ? " — Google sign-in still works too." : "."), "success")
    }
} finally { if (!_d) ec.artifactExecution.enableAuthz() }
